// The demo case as fixtures: "NYC trip for the Nov 13 conference, under $1,500", booked with the wrong date (Nov 3),
// and the corrected bookings for Nov 13 that the redo makes.
//
//   npx tsx evals/demo-fixtures.ts      writes fixtures/demo/
//
// Everything is generated by booking through the real mock merchants, so the emails carry real schema.org markup
// and the refs are what the merchants really issue. The files are committed; a test fails if they go stale.

import { mkdirSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import type { Intent, LogIntentInput } from "../src/types.js";
import { type SimBooking, type SimWorld, simulateBookings } from "./sim.js";

export const DEMO_TASK_ID = "task_nyc";
export const DEMO_TASK_EMAIL = "task_nyc@tasks.proxy.example";

export const DEMO_LOG_INTENT: LogIntentInput = {
  goal: "NYC trip for the Nov 13 conference, under $1,500",
  constraints: { dates: { start: "2026-11-13", end: "2026-11-16" }, budget_total: 150000 },
  preferences: { no_store_credit: true, min_partial_refund_pct: 80, auto_undo: false },
  idempotency_key: "demo-nyc-trip",
};

export const DEMO_INTENT: Intent = {
  task_id: DEMO_TASK_ID,
  task_email: DEMO_TASK_EMAIL,
  goal: DEMO_LOG_INTENT.goal,
  constraints: DEMO_LOG_INTENT.constraints,
  preferences: { no_store_credit: true, min_partial_refund_pct: 80, auto_undo: false },
  created_at: "2026-10-17T09:00:00.000Z",
};

/** What the agent booked: everything for Nov 3. The hotel's confirmation arrives late, after the agent has left. */
export const WRONG_BOOKINGS: SimBooking[] = [
  { id: "flight", merchant_id: "airline", item: "SFO-JFK", dates: { start: "2026-11-03" }, amount: 41200, booked_at: "2026-10-17T09:00:00.000Z" },
  {
    id: "hotel",
    merchant_id: "hotel",
    item: "Harborview Hotel, 3 nights",
    dates: { start: "2026-11-03", end: "2026-11-06" },
    amount: 64000,
    booked_at: "2026-10-17T09:10:00.000Z",
    confirm_at: "2026-10-17T11:00:00.000Z",
  },
  {
    id: "transfer",
    merchant_id: "transfer",
    item: "Airport transfer, JFK to Harborview Hotel",
    dates: { start: "2026-11-03" },
    amount: 18800,
    booked_at: "2026-10-17T09:15:00.000Z",
  },
  {
    id: "host_email",
    merchant_id: "host",
    item: "Arrival email to the host: arriving 2026-11-03",
    dates: { start: "2026-11-03" },
    amount: 0,
    booked_at: "2026-10-17T09:25:00.000Z",
  },
];

/** What the redo books after the undo: the same trip for Nov 13 to 16. */
export const CORRECT_BOOKINGS: SimBooking[] = [
  { id: "flight", merchant_id: "airline", item: "SFO-JFK", dates: { start: "2026-11-13" }, amount: 41200, booked_at: "2026-10-18T06:00:00.000Z" },
  {
    id: "hotel",
    merchant_id: "hotel",
    item: "Harborview Hotel, 3 nights",
    dates: { start: "2026-11-13", end: "2026-11-16" },
    amount: 64000,
    booked_at: "2026-10-18T06:05:00.000Z",
  },
  {
    id: "transfer",
    merchant_id: "transfer",
    item: "Airport transfer, JFK to Harborview Hotel",
    dates: { start: "2026-11-13" },
    amount: 18800,
    booked_at: "2026-10-18T06:10:00.000Z",
  },
  {
    id: "host_email",
    merchant_id: "host",
    item: "Arrival email to the host: arriving 2026-11-13",
    dates: { start: "2026-11-13" },
    amount: 0,
    booked_at: "2026-10-18T06:15:00.000Z",
  },
];

export interface DemoFixtures {
  wrong: SimWorld;
  correct: SimWorld;
}

export async function buildDemoFixtures(): Promise<DemoFixtures> {
  const common = { task_id: DEMO_TASK_ID, task_email: DEMO_TASK_EMAIL };
  return {
    wrong: await simulateBookings({ ...common, bookings: WRONG_BOOKINGS }),
    correct: await simulateBookings({ ...common, bookings: CORRECT_BOOKINGS }),
  };
}

/** The files written under fixtures/demo/, as path -> content. Used by the writer and by the staleness test. */
export async function demoFixtureFiles(): Promise<Record<string, string>> {
  const { wrong, correct } = await buildDemoFixtures();
  const json = (value: unknown): string => `${JSON.stringify(value, null, 2)}\n`;
  const files: Record<string, string> = {
    "intent.json": json({ log_intent: DEMO_LOG_INTENT, intent: DEMO_INTENT }),
    "bookings-wrong.json": json(WRONG_BOOKINGS),
    "bookings-correct.json": json(CORRECT_BOOKINGS),
  };
  for (const [name, world] of [["wrong", wrong], ["correct", correct]] as const) {
    files[`${name}/actions.json`] = json(world.actions);
    files[`${name}/stripe-events.json`] = json(world.stripe_events);
    for (const { id, email } of world.emails) {
      files[`${name}/emails/${id}.html`] = `${email.html}\n`;
      files[`${name}/emails/${id}.txt`] = `From: ${email.from.name} <${email.from.address}>\nTo: ${email.to}\nSubject: ${email.subject}\n\n${email.body}\n`;
    }
  }
  return files;
}

export async function writeDemoFixtures(dir: string): Promise<string[]> {
  const files = await demoFixtureFiles();
  for (const [path, content] of Object.entries(files)) {
    const full = join(dir, path);
    mkdirSync(dirname(full), { recursive: true });
    writeFileSync(full, content);
  }
  return Object.keys(files).sort();
}

// Run directly: write the files into fixtures/demo/.
if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const target = join(dirname(fileURLToPath(import.meta.url)), "..", "fixtures", "demo");
  const written = await writeDemoFixtures(target);
  console.log(`Wrote ${written.length} files to fixtures/demo/`);
}
